{"path": "src/semver.js", "content": "// compareVersions(a, b) → -1, 0 or 1 following Semantic Versioning 2.0.0 precedence
// (including pre-release identifiers; build metadata after '+' is ignored).
export function compareVersions(a, b) {
  const va = parse(a);
  const vb = parse(b);
  for (let i = 0; i < 3; i++) {
    if (va.core[i] !== vb.core[i]) return va.core[i] < vb.core[i] ? -1 : 1;
  }
  return comparePrerelease(va.pre, vb.pre);
}

function parse(version) {
  const withoutBuild = String(version).split('+')[0];
  const dash = withoutBuild.indexOf('-');
  const corePart = dash === -1 ? withoutBuild : withoutBuild.slice(0, dash);
  const prePart = dash === -1 ? '' : withoutBuild.slice(dash + 1);
  const core = corePart.split('.').map(Number);
  return { core, pre: prePart === '' ? [] : prePart.split('.') };
}

const NUMERIC = /^\d+$/;

function comparePrerelease(pa, pb) {
  // A version without pre-release has higher precedence than one with it.
  if (pa.length === 0 || pb.length === 0) {
    if (pa.length === pb.length) return 0;
    return pa.length === 0 ? 1 : -1;
  }
  const len = Math.min(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const x = pa[i];
    const y = pb[i];
    if (x === y) continue;
    const xNum = NUMERIC.test(x);
    const yNum = NUMERIC.test(y);
    if (xNum && yNum) {
      // Compare numerically without precision loss for long identifiers.
      if (x.length !== y.length) return x.length < y.length ? -1 : 1;
      return x < y ? -1 : 1;
    }
    // Numeric identifiers have lower precedence than alphanumeric ones.
    if (xNum) return -1;
    if (yNum) return 1;
    // ASCII lexical comparison.
    return x < y ? -1 : 1;
  }
  if (pa.length === pb.length) return 0;
  return pa.length < pb.length ? -1 : 1;
}
"}

